import{_ as a,c as o,o as e,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"微信公众号配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-wechat.md","filePath":"platforms/custom-wechat.md","lastUpdated":1790228279000}'),i={name:"platforms/custom-wechat.md"};function d(l,t,n,s,c,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="微信公众号配置指南" tabindex="-1">微信公众号配置指南 <a class="header-anchor" href="#微信公众号配置指南" aria-label="Permalink to &quot;微信公众号配置指南&quot;">​</a></h1><p>通过登录公众号后台的 <strong>Cookie</strong> 发布到微信公众号。以 HTML 内容发布，图片默认上传到公众号素材库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>用<strong>公众号管理员</strong>的微信扫码登录公众号后台 <code>https://mp.weixin.qq.com</code>。</li><li>保持该浏览器会话登录状态（后续读取 Cookie 用）。</li><li>无需 AppID/AppSecret（通过浏览器 Cookie 发布）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://mp.weixin.qq.com</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认公众号后台接口地址，一般不改</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>公众号文章编辑页 URL 模板，一般不改</td></tr><tr><td>发布格式</td><td>默认 HTML</td></tr><tr><td>图床</td><td>默认「当前平台」（公众号素材库）</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 用公众号管理员微信扫码登录 mp.weixin.qq.com → 关闭窗口 → 点「2 自动读取 Cookie」→ 验证。</li><li>快速发布 → 选公众号 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>Cookie 验证失败</strong>：确认已用公众号管理员账号登录 mp.weixin.qq.com（微信扫码登录），重新读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」即可。公众号通过素材库接口上传图片，不依赖本机 PicGo 服务。</li><li><strong>发布成功但内容为空</strong>：公众号以 HTML 内容发布。若文档为纯 Markdown，请确认文档能正确渲染为 HTML 后再发布。</li></ul>',10)])])}const u=a(i,[["render",d]]);export{p as __pageData,u as default};
